const express = require('express');
const session = require('express-session');
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcrypt');

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required');

const app = express();
app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    maxAge: 1000 * 60 * 60 * 2,
  },
}));

const users = new Map(); // username -> { hash }
const ROUNDS = 12;
// Compared against when the user doesn't exist, so response time doesn't reveal valid usernames.
const DUMMY_HASH = bcrypt.hashSync('dummy', ROUNDS);

// 5 failed attempts per IP per 15 minutes; successful logins don't count.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed attempts, try again later' },
});

const credentials = (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' || !username) {
    return res.status(400).json({ error: 'Username and password are required' });
  }
  next();
};

app.post('/register', credentials, async (req, res) => {
  const { username, password } = req.body;
  // bcrypt ignores everything past 72 bytes.
  if (password.length < 8 || Buffer.byteLength(password) > 72) {
    return res.status(400).json({ error: 'Password must be 8 to 72 bytes' });
  }
  if (users.has(username)) return res.status(409).json({ error: 'Username taken' });
  users.set(username, { hash: await bcrypt.hash(password, ROUNDS) });
  res.status(201).json({ ok: true });
});

app.post('/login', loginLimiter, credentials, async (req, res) => {
  const { username, password } = req.body;
  const user = users.get(username);
  const ok = await bcrypt.compare(password, user ? user.hash : DUMMY_HASH);
  if (!user || !ok) return res.status(401).json({ error: 'Invalid username or password' });

  // New session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: 'Login failed' });
    req.session.userId = username;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res) => {
  req.session.destroy(() => {
    res.clearCookie('connect.sid');
    res.json({ ok: true });
  });
});

